 TB("VERIFICAR VALORES",["Ecuación","Valor","Resultado"],[["4x − 5 = 7","x = 3","7 = 7 ✓"],["5x − 1 = 8","x = 2","9 ≠ 8"],["x/3 + 2 = 5","x = 9","5 = 5 ✓"]],["Se reemplaza el valor y se compara.","Con *equis tres*, siete es igual a siete: *sí es solución*.","Con *equis dos*, nueve no es ocho: *no es solución*.","Y con *equis nueve*, cinco es igual a cinco: *sí es solución*."]),
 SIS("VERIFICACIÓN",("Se reemplaza","📥"),[("dato","Ecuación: 4x − 5 = 7"),("dato","Valor: x = 3")],[("resultado","7 = 7: verifica")],["Veamos las partes de una verificación.","La ecuación es cuatro equis menos cinco igual siete.","El valor propuesto es equis igual tres.","Se reemplaza, y los dos miembros coinciden: *verifica*."]),
